add_action( 'woocommerce_after_add_to_cart_form', 'perfectpixel_variation_selects_in_order' );

function perfectpixel_variation_selects_in_order() {
	global $product;
	if ( ! $product || ! $product->is_type( 'variable' ) ) {
		return;
	}
	?>
	<script>
	jQuery( function ( $ ) {
		$( 'form.variations_form' ).each( function () {
			var form    = $( this );
			var refresh = function () {
				var open = true;
				form.find( 'table.variations select' ).each( function () {
					var select = $( this );
					if ( ! open ) {
						select.val( '' );
					}
					select.prop( 'disabled', ! open );
					open = open && '' !== select.val();
				} );
			};
			form.on( 'change', 'table.variations select', refresh ).on( 'reset_data', function () {
				setTimeout( refresh );
			} );
			refresh();
		} );
	} );
	</script>
	<?php
}
